export const meta = {
  name: 'review-merged-reader-changes',
  description: 'Adversarially review the cherry-picked kudos/narration changes against reader invariants before App Store release',
  phases: [
    { title: 'Review' },
    { title: 'Verify' },
  ],
}

// The merged diff (PR #15/#16, cherry-picked) — three files.
const DIFF = `
FILE: Fanficly/Search/SearchView.swift (WorkRow kudos label)
- Label(work.kudos.formatted(), systemImage: "heart").font(.caption).foregroundStyle(.secondary)
+ Label(work.kudos.formatted(), systemImage: "heart")
+   .font(.caption).foregroundStyle(.secondary)
+   .lineLimit(1)
+   .fixedSize(horizontal: true, vertical: false)

FILE: Fanficly/Library/LibraryView.swift (LibraryRow Finished)
- Label("Finished", systemImage: "checkmark.circle.fill").foregroundStyle(.green)
+ HStack(spacing: 4) { Image(systemName: "checkmark.circle.fill"); Text("Finished") }.foregroundStyle(.green)

FILE: Fanficly/Reader/ReaderView.swift (narration)
- startNarration(): chapterIndex = (mode == .paginated ? selectedChapterIndex : visibleChapterIndex); from = (currentAnchor?.chapter == chapterIndex) ? (currentAnchor?.paragraph ?? 0) : 0; narrate(chapter: chapterIndex, from: from)
+ startNarration(): if let anchor = currentAnchor { narrate(chapter: anchor.chapter, from: anchor.paragraph) } else { narrate(chapter: effectiveChapterIndex, from: 0) }
+ NEW narrate(toChapter index:): guard index != listeningChapter; selectedChapterIndex = index; visibleChapterIndex = index; narrate(chapter: index, from: 0)
+ narration bar: if chapters.count > 1 -> Menu { Picker("Chapter", selection: chapterNarrationBinding) { ForEach(chapters, id: .index) ... } } label: { narrationStatus(fg:, showChevron: true) } else narrationStatus(showChevron:false)
+ NEW narrationStatus(fg:showChevron:) -> chapterLabel + optional chevron.up.chevron.down + "¶ x / y"
+ NEW chapterNarrationBinding: get { listeningChapter ?? effectiveChapterIndex } set { narrate(toChapter: $0) }
`

const INVARIANTS = `Reader invariants from CLAUDE.md (regressions here are blockers):
- TTS "Listen" speechParagraphs are INDEX-ALIGNED with rendered paragraphs; the highlight/auto-scroll and chapter auto-advance rely on this.
- On finish, SpeechController bumps finishedTick and ReaderView auto-advances to the next chapter (signal, not stored closure, to avoid retain cycle).
- Reader uses plain system nav bar (no auto-hide); never use .preferredColorScheme in the reader.
- Reader story text is intentionally NOT selectable.
- Paginated mode shows the Listen bar; continuous mode shows a chapter indicator; hardware arrow keys turn pages.
- listeningChapter is the chapter currently being narrated; effectiveChapterIndex is the reader's current chapter; currentAnchor carries (chapter, paragraph).`

const FINDINGS_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        properties: {
          title: { type: 'string' },
          file: { type: 'string' },
          severity: { type: 'string', enum: ['blocker','high','medium','low'] },
          detail: { type: 'string' },
          suggestion: { type: 'string' },
        },
        required: ['title','file','severity','detail','suggestion'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    isReal: { type: 'boolean' },
    severity: { type: 'string', enum: ['blocker','high','medium','low','not-a-bug'] },
    reasoning: { type: 'string' },
  },
  required: ['isReal','severity','reasoning'],
}

const DIMENSIONS = [
  { key: 'logic', prompt: `You are reviewing merged narration changes for CORRECTNESS and STATE bugs (off-by-one, wrong chapter/paragraph, binding loops, guard mistakes). Read Fanficly/Reader/ReaderView.swift in full to confirm referenced symbols (effectiveChapterIndex, listeningChapter, chapters with .index/.title, currentAnchor with .chapter/.paragraph, selectedChapterIndex, visibleChapterIndex, narrate(chapter:from:), speech.chapterLabel/spokenPosition/spokenCount) EXIST and have the expected shape, and that the new startNarration / narrate(toChapter:) / chapterNarrationBinding logic is correct. Report only real issues.` },
  { key: 'invariants', prompt: `You are reviewing the merged narration change for REGRESSIONS against the reader invariants below. Read Fanficly/Reader/ReaderView.swift and Fanficly/Reader/SpeechController.swift as needed. Does adding the chapter Picker / jumping chapters during narration break TTS index-alignment, karaoke highlight, auto-scroll, or chapter auto-advance? Does narrate(toChapter:) correctly resync the visible page? ${INVARIANTS}` },
  { key: 'ui', prompt: `You are reviewing the SwiftUI layout/binding changes. The kudos Label gets .lineLimit(1).fixedSize(horizontal:true). The Finished Label becomes an HStack of Image+Text. The narration status becomes a Menu+Picker when chapters.count>1. Read Fanficly/Search/SearchView.swift, Fanficly/Library/LibraryView.swift, and the narration bar in Fanficly/Reader/ReaderView.swift. Check for layout overflow, accessibility, Picker/Menu binding correctness, and whether fixedSize could push other row content offscreen on small iPhones.` },
]

phase('Review')
const reviewed = await pipeline(
  DIMENSIONS,
  (d) => agent(`${d.prompt}\n\nMerged diff under review:\n${DIFF}\n\nReturn findings (empty array if none).`, { label: `review:${d.key}`, phase: 'Review', schema: FINDINGS_SCHEMA }),
  (res, d) => {
    const findings = (res && res.findings) || []
    if (!findings.length) return []
    return parallel(findings.map((f) => () =>
      agent(`Adversarially verify this claimed issue in the merged reader/kudos changes. Read the actual file(s) to confirm. Default to isReal=false unless you can demonstrate a concrete, real problem in THIS code (not hypothetical). Claim:\nTitle: ${f.title}\nFile: ${f.file}\nSeverity: ${f.severity}\nDetail: ${f.detail}\nSuggestion: ${f.suggestion}`,
        { label: `verify:${(f.file||'').split('/').pop()}`, phase: 'Verify', schema: VERDICT_SCHEMA })
        .then((v) => ({ ...f, verdict: v }))
    ))
  }
)

const confirmed = reviewed.flat().filter(Boolean).filter((f) => f.verdict && f.verdict.isReal)
return {
  totalRaw: reviewed.flat().filter(Boolean).length,
  confirmedCount: confirmed.length,
  confirmed: confirmed.map((f) => ({ title: f.title, file: f.file, severity: f.verdict.severity, detail: f.detail, suggestion: f.suggestion, why: f.verdict.reasoning })),
}

